import{_ as a,o as s,c as r,a2 as t}from"./chunks/framework.DT_qyuxR.js";const m=JSON.parse('{"title":"Conseils pour les Vivants","description":"","frontmatter":{},"headers":[],"relativePath":"guide-joueur/02-conseils-vivants.md","filePath":"guide-joueur/02-conseils-vivants.md"}'),i={name:"guide-joueur/02-conseils-vivants.md"};function o(n,e,u,l,c,p){return s(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="conseils-pour-les-vivants" tabindex="-1">Conseils pour les Vivants <a class="header-anchor" href="#conseils-pour-les-vivants" aria-label="Permalink to &quot;Conseils pour les Vivants&quot;">​</a></h1><h2 id="votre-objectif" tabindex="-1">Votre objectif <a class="header-anchor" href="#votre-objectif" aria-label="Permalink to &quot;Votre objectif&quot;">​</a></h2><p>Vous êtes Vivant. Vous devez <strong>éliminer tous les Revenants</strong> avant qu&#39;ils ne vous éliminent tous. Vous ne savez pas qui sont les Revenants — c&#39;est le défi.</p><h2 id="strategies-de-base" tabindex="-1">Stratégies de base <a class="header-anchor" href="#strategies-de-base" aria-label="Permalink to &quot;Stratégies de base&quot;">​</a></h2><h3 id="_1-reseaux" tabindex="-1">1. Réseaux <a class="header-anchor" href="#_1-reseaux" aria-label="Permalink to &quot;1. Réseaux&quot;">​</a></h3><p>Pendant les Débats, parlez aux autres joueurs. Créez des alliances. Les Vivants qui travaillent ensemble survivent plus longtemps.</p><h3 id="_2-accusez-sans-preuve" tabindex="-1">2. Accusez sans preuve <a class="header-anchor" href="#_2-accusez-sans-preuve" aria-label="Permalink to &quot;2. Accusez sans preuve&quot;">​</a></h3><p>Vous n&#39;avez pas de preuve, mais les accusations créent de la panique. Un Revenant accusé va se défendre — et se défendre, c&#39;est révéler des indices.</p><h3 id="_3-ecoutez-les-rumeurs" tabindex="-1">3. Écoutez les rumeurs <a class="header-anchor" href="#_3-ecoutez-les-rumeurs" aria-label="Permalink to &quot;3. Écoutez les rumeurs&quot;">​</a></h3><p>Quand un joueur meurt, sa rumeur peut contenir un indice. Un Vivant mort va probablement laisser un indice sur un Revenant. Un Revenant mort va probablement mentir.</p><h3 id="_4-utilisez-les-masques-informationnels" tabindex="-1">4. Utilisez les masques informationnels <a class="header-anchor" href="#_4-utilisez-les-masques-informationnels" aria-label="Permalink to &quot;4. Utilisez les masques informationnels&quot;">​</a></h3><p>Si vous portez un masque avec des capacités d&#39;information (Medium, Oracle, Sans-Visage), utilisez-les. Vous êtes les yeux des Vivants.</p><h3 id="_5-protegez-les-allies-utiles" tabindex="-1">5. Protégez les alliés utiles <a class="header-anchor" href="#_5-protegez-les-allies-utiles" aria-label="Permalink to &quot;5. Protégez les alliés utiles&quot;">​</a></h3><p>Si un joueur a un masque puissant (Medium, Oracle, Sans-Visage), protégez-le. Les Revenants vont le cibler en premier.</p><h2 id="erreurs-a-eviter" tabindex="-1">Erreurs à éviter <a class="header-anchor" href="#erreurs-a-eviter" aria-label="Permalink to &quot;Erreurs à éviter&quot;">​</a></h2><h3 id="accuser-tout-le-monde" tabindex="-1">Accuser tout le monde <a class="header-anchor" href="#accuser-tout-le-monde" aria-label="Permalink to &quot;Accuser tout le monde&quot;">​</a></h3><p>Si vous accusez tout le monde, personne ne vous croira. Concentrez-vous sur les suspects.</p><h3 id="ignorer-les-debats" tabindex="-1">Ignorer les Débats <a class="header-anchor" href="#ignorer-les-debats" aria-label="Permalink to &quot;Ignorer les Débats&quot;">​</a></h3><p>Les Débats sont votre principale source d&#39;information. Ne les négligez pas.</p><h3 id="reveler-votre-camp" tabindex="-1">Révéler votre camp <a class="header-anchor" href="#reveler-votre-camp" aria-label="Permalink to &quot;Révéler votre camp&quot;">​</a></h3><p>Ne dites jamais explicitement que vous êtes Vivant. Les Revenants vont vous cibler.</p><h3 id="jouer-trop-passivement" tabindex="-1">Jouer trop passivement <a class="header-anchor" href="#jouer-trop-passivement" aria-label="Permalink to &quot;Jouer trop passivement&quot;">​</a></h3><p>Un Vivant passif est un Vivant mort. Utilisez vos pouvoirs, participez aux Duels, agissez.</p><h2 id="strategies-avancees" tabindex="-1">Stratégies avancées <a class="header-anchor" href="#strategies-avancees" aria-label="Permalink to &quot;Stratégies avancées&quot;">​</a></h2><h3 id="le-piege" tabindex="-1">Le piège <a class="header-anchor" href="#le-piege" aria-label="Permalink to &quot;Le piège&quot;">​</a></h3><p>Accusez un joueur pour voir comment il réagit. Un Revenant va se défendre nerveusement. Un Vivant va se défendre calmement.</p><h3 id="le-sacrifice" tabindex="-1">Le sacrifice <a class="header-anchor" href="#le-sacrifice" aria-label="Permalink to &quot;Le sacrifice&quot;">​</a></h3><p>Si vous êtes un masque faible (10-12 PV), sacrificez-vous pour identifier un Revenant. Votre mort peut révéler des indices.</p><h3 id="le-compteur" tabindex="-1">Le compteur <a class="header-anchor" href="#le-compteur" aria-label="Permalink to &quot;Le compteur&quot;">​</a></h3><p>Mémorisez les PV des masques. Si un joueur a reçu beaucoup de dégâts, il est probablement à bout. Défiez-le en Duel.</p><h2 id="conseils-par-masque" tabindex="-1">Conseils par masque <a class="header-anchor" href="#conseils-par-masque" aria-label="Permalink to &quot;Conseils par masque&quot;">​</a></h2><h3 id="si-vous-portez-le-medium-ou-l-oracle" tabindex="-1">Si vous portez le Medium ou l&#39;Oracle <a class="header-anchor" href="#si-vous-portez-le-medium-ou-l-oracle" aria-label="Permalink to &quot;Si vous portez le Medium ou l&#39;Oracle&quot;">​</a></h3><p>Vous êtes l&#39;investigateur principal. Examinez les joueurs suspects chaque nuit (Medium) ou défiez-les en Duel pour connaître leur camp (Oracle). Votre information est essentielle.</p><h3 id="si-vous-portez-le-vampire-ou-l-empathique" tabindex="-1">Si vous portez le Vampire ou l&#39;Empathique <a class="header-anchor" href="#si-vous-portez-le-vampire-ou-l-empathique" aria-label="Permalink to &quot;Si vous portez le Vampire ou l&#39;Empathique&quot;">​</a></h3><p>Vous êtes le soigneur. Maintenez les alliés en vie. Soignez les joueurs blessés. Vous êtes une cible prioritaire pour les Revenants — protégez-vous.</p><h3 id="si-vous-portez-un-masque-offensif" tabindex="-1">Si vous portez un masque offensif <a class="header-anchor" href="#si-vous-portez-un-masque-offensif" aria-label="Permalink to &quot;Si vous portez un masque offensif&quot;">​</a></h3><p>Vous êtes le bras armé des Vivants. Utilisez vos dégâts pour éliminer les Revenants. Ne les gaspillez pas sur des Vivants.</p>',37)])])}const v=a(i,[["render",o]]);export{m as __pageData,v as default};
